    (OUT/'report.md').write_text(text,encoding='utf8')
    files=[p for p in OUT.iterdir() if p.is_file() and p.name not in {'AUTHORITY.json','HASHES.json'} and p.suffix in {'.json','.md','.log','.txt'}]
